-- Function: public.fn_get_child_care_plans_by_branch
-- Backup generated on 2026-10-25 20:33:08

CREATE OR REPLACE FUNCTION public.fn_get_child_care_plans_by_branch(p_tenant_id uuid, p_branch_id uuid)  RETURNS TABLE(id uuid, tenant_id uuid, organization_id uuid, branch_id uuid, child_id uuid, version integer, diaper_routine_guidance text, feeding_instructions text, bottle_schedule_guidance text, sleep_routine_guidance text, toileting_support_plan text, comfort_calming_preferences text, required_supplies_note text, dietary_allergies_summary text, effective_date date, review_date date, status character varying, created_by_user_id uuid, approved_by_user_id uuid, approved_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, child_name text)  LANGUAGE sql  STABLE AS $function$     SELECT p.id, p.tenant_id, p.organization_id, p.branch_id, p.child_id, p.version,            p.diaper_routine_guidance, p.feeding_instructions, p.bottle_schedule_guidance,            p.sleep_routine_guidance, p.toileting_support_plan, p.comfort_calming_preferences,            p.required_supplies_note, p.dietary_allergies_summary, p.effective_date, p.review_date,            p.status, p.created_by_user_id, p.approved_by_user_id, p.approved_at, p.created_at, p.updated_at,            CONCAT(c.first_name, ' ', c.last_name) AS child_name     FROM child_care_plans p     JOIN children c ON p.child_id = c.id     WHERE p.tenant_id = p_tenant_id        AND p.branch_id = p_branch_id        AND p.status = 'Active'     ORDER BY c.first_name ASC; $function$ ;
